UntypedValue* Context::Create(std::string const& name)
{
    RazorfenKraulAvoidanceValueContext factory;
    auto i = factory.creators.find(name);
    return i == factory.creators.end() ? nullptr : i->second(ai);
}
int main()
{
    Player bot;
    bot.map = 47;
    PlayerbotAI ai(&bot);
    Creature caster(12);
    caster.map = 47;
    ai.units[caster.guid] = &caster;
    ai.context.GetValue<GuidVector>("attackers")->Set({caster.guid});
    sPlayerbotAIConfig.EnableRazorfenKraulMechanics = true;
    SpellInfo nova;
    nova.Id = 8259;
    for (auto& effect : nova.Effects)
        effect.radius = 9;
    Spell cast{&nova, {}};
    caster.currentSpell[CURRENT_GENERIC_SPELL] = &cast;
    auto area = RazorfenKraul::CollectHazard(&ai);
    assert(area.active && area.radius == 12);
    caster.z = 40;
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    caster.z = 0;
    caster.x = 12;
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    caster.x = 0;
    nova.Id = 18070;
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    nova.Id = 8259;
    bot.combat = false;
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    bot.combat = true;
    clockNow += 250;
    RazorfenKraulEscapeAction escape(&ai);
    ai.canMove = false;
    int beforeRoot = bot.castStops;
    assert(!escape.isUseful() && !escape.Execute({}));
    assert(bot.castStops == beforeRoot);
    ai.canMove = true;
    nova.Id = 8259;
    assert(RazorfenKraul::CollectHazard(&ai).active);
    nova.Id = 8259;
    int initialMoves = ai.moves;
    for (int step = 0; step < 3; ++step)
    {
        clockNow += 600;
        assert(escape.Execute({}));
        assert(ai.moves == initialMoves + step + 1);
        assert(bot.spline.destination.x == bot.x + 5);
        clockNow += 100;
        assert(escape.Execute({}) && ai.moves == initialMoves + step + 1);
        bot.Relocate(bot.spline.destination.x, bot.spline.destination.y, bot.spline.destination.z);
        bot.spline.done = true;
        bot.moving = false;
    }
    assert(bot.x == 15 && !RazorfenKraul::CollectHazard(&ai).active && !escape.Execute({}));
    bot.x = 0;
    ai.fleeDistance = 0;
    int beforeFailure = bot.castStops;
    clockNow += 600;
    assert(!escape.Execute({}) && !bot.moving && bot.spline.done);
    assert(bot.castStops == beforeFailure);
    ai.fleeDistance = 5;
    ai.moveBlocked = true;
    clockNow += 600;
    assert(!escape.Execute({}));
    int clears = ai.movement.clears;
    clockNow += 100;
    assert(!escape.Execute({}) && ai.movement.clears == clears);
    assert(bot.castStops == beforeFailure && ai.movement.clears == clears);
    ai.moveBlocked = false;
    ai.pathRejected = true;
    clockNow += 600;
    assert(!escape.Execute({}) && bot.castStops == beforeFailure && ai.movement.clears == clears);
    ai.pathRejected = false;
    bot.movementCast = true;
    clockNow += 600;
    assert(escape.Execute({}) && bot.castStops == beforeFailure + 1);
    assert(bot.deferredMove && bot.spline.done && !bot.movementCast);
    bot.MovementUpdate();
    int acceptedMoves = ai.moves;
    clockNow += 100;
    assert(escape.Execute({}) && ai.moves == acceptedMoves && bot.castStops == beforeFailure + 1);
    assert(!bot.spline.done && bot.spline.destination.x == 5);
    caster.currentSpell[CURRENT_GENERIC_SPELL] = nullptr;
    clockNow += 250;
    caster.currentSpell[CURRENT_GENERIC_SPELL] = &cast;
    bot.map = 0;
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    bot.map = 47;
    sPlayerbotAIConfig.EnableRazorfenKraulMechanics = false;
    assert(!RazorfenKraul::InHazard(&ai) && !RazorfenKraul::CollectHazard(&ai).active);
    sPlayerbotAIConfig.EnableRazorfenKraulMechanics = true;
    bot.combat = false;
    bot.Relocate(0, 0, 0);
    GameObject fire;
    ai.objects[ObjectGuid(90)] = &fire;
    ai.context.GetValue<GuidVector>("nearest game objects no los")->Set({ObjectGuid(90)});
    assert(RazorfenKraul::CollectHazard(&ai).active);
    sGameObjectDisplayInfoStore.present = true;
    fire.scale = 2.0f;
    bot.Relocate(6.1f, 4.1f, 0);
    auto bounds = RazorfenKraul::CollectHazard(&ai);
    assert(bounds.active && bounds.radius >= std::hypot(7.3f, 5.3f));
    bot.Relocate(8, 0, 0);
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    sGameObjectDisplayInfoStore.present = false;
    bot.Relocate(0, 0, 0);
    fire.z = 10;
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    fire.z = 0;
    fire.spawned = false;
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    fire.spawned = true;
    fire.entry = 21099;
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    fire.entry = 69431;
    sPlayerbotAIConfig.EnableRazorfenKraulMechanics = false;
    assert(!RazorfenKraul::CollectHazard(&ai).active);
    std::cout << "RazorfenKraul source execution scenarios passed\n";
}
